echo "K3 LoopBrace useArrangement calls: $(grep -c 'useArrangement()' $C/ArrangementLoopBrace.tsx) arrangement.loop reads: $(grep -cE 'arrangement\.loop' $C/ArrangementLoopBrace.tsx) memo: $(grep -c 'memo(ArrangementLoopBraceViewInner)' $C/ArrangementLoopBrace.tsx) actions hook: $(grep -c '^export function useArrangementLoopBraceActions' $C/ArrangementLoopBrace.tsx)"
