echo "K19 doc 244: files $(ls $D | grep -c '^244-') l.4 '$(sed -n 4p $D/244-perf-loop-brace-leaf.md 2>/dev/null)' mentions RB-LEAF5 $(grep -c 'RB-LEAF5' $D/244-perf-loop-brace-leaf.md 2>/dev/null)"
